package exercise

import (
	"reflect"
	"testing"
	"time"
)

func TestStronglyConnected(t *testing.T) {
	cases := []struct {
		name string
		n    int
		adj  [][]int
		want [][]int
	}{
		{
			name: "two loops and a sink",
			n:    6,
			adj:  [][]int{{1}, {2}, {0, 3}, {4}, {3, 5}, {}},
			want: [][]int{{0, 1, 2}, {3, 4}, {5}},
		},
		{
			name: "one-way chain",
			n:    3,
			adj:  [][]int{{1}, {2}, {}},
			want: [][]int{{0}, {1}, {2}},
		},
		{
			name: "edge from a vertex to itself",
			n:    2,
			adj:  [][]int{{0, 1}, {1}},
			want: [][]int{{0}, {1}},
		},
		{
			name: "no edges",
			n:    3,
			adj:  [][]int{{}, {}, {}},
			want: [][]int{{0}, {1}, {2}},
		},
		{
			name: "every vertex reaches every other",
			n:    4,
			adj:  [][]int{{1, 2, 3}, {0, 2, 3}, {0, 1, 3}, {0, 1, 2}},
			want: [][]int{{0, 1, 2, 3}},
		},
		{
			name: "separate pieces",
			n:    5,
			adj:  [][]int{{1}, {0}, {}, {4}, {3}},
			want: [][]int{{0, 1}, {2}, {3, 4}},
		},
		{
			name: "loop visited out of numeric order",
			n:    3,
			adj:  [][]int{{2}, {0}, {1}},
			want: [][]int{{0, 1, 2}},
		},
		{
			name: "edge into a group already found in the same search",
			n:    4,
			adj:  [][]int{{1, 3}, {2}, {1}, {2}},
			want: [][]int{{0}, {1, 2}, {3}},
		},
		{
			name: "edge into a group found by an earlier search",
			n:    3,
			adj:  [][]int{{}, {0, 2}, {1}},
			want: [][]int{{0}, {1, 2}},
		},
		{
			name: "single vertex",
			n:    1,
			adj:  [][]int{{}},
			want: [][]int{{0}},
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := StronglyConnected(c.n, c.adj)
			if !reflect.DeepEqual(got, c.want) {
				t.Errorf("got %v, want %v", got, c.want)
			}
		})
	}
}

func TestStronglyConnectedHandlesLargeGraph(t *testing.T) {
	// Pairs 2k <-> 2k+1, each pair leading one way into the next. Every
	// vertex reaches every later one, so checking reachability from each
	// vertex walks most of the graph every time.
	const n = 100000
	adj := make([][]int, n)
	for k := 0; k < n; k += 2 {
		adj[k] = append(adj[k], k+1)
		adj[k+1] = append(adj[k+1], k)
		if k+2 < n {
			adj[k+1] = append(adj[k+1], k+2)
		}
	}

	const budget = 2 * time.Second
	done := make(chan [][]int, 1)
	go func() { done <- StronglyConnected(n, adj) }()

	var got [][]int
	select {
	case got = <-done:
	case <-time.After(budget):
		t.Fatalf("still running after %v on a graph of %d vertices: sort every vertex into its group in a single traversal", budget, n)
	}

	if len(got) != n/2 {
		t.Fatalf("got %d groups, want %d", len(got), n/2)
	}
	for i, g := range got {
		if want := []int{2 * i, 2*i + 1}; !reflect.DeepEqual(g, want) {
			t.Fatalf("group %d: got %v, want %v", i, g, want)
		}
	}
}

