package exercise

import "sort"

func StronglyConnected(n int, adj [][]int) [][]int {
	disc := make([]int, n)
	low := make([]int, n)
	for i := range disc {
		disc[i] = -1
	}
	onStack := make([]bool, n)
	var stack []int
	var groups [][]int
	time := 0

	var visit func(u int)
	visit = func(u int) {
		disc[u] = time
		low[u] = time
		time++
		stack = append(stack, u)
		onStack[u] = true

		for _, v := range adj[u] {
			if disc[v] == -1 {
				visit(v)
				low[u] = min(low[u], low[v])
			} else if onStack[v] {
				low[u] = min(low[u], disc[v])
			}
		}

		if low[u] == disc[u] {
			var group []int
			for {
				v := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				onStack[v] = false
				group = append(group, v)
				if v == u {
					break
				}
			}
			sort.Ints(group)
			groups = append(groups, group)
		}
	}

	for u := 0; u < n; u++ {
		if disc[u] == -1 {
			visit(u)
		}
	}

	sort.Slice(groups, func(i, j int) bool { return groups[i][0] < groups[j][0] })
	return groups
}
